package config_test

import (
	"bytes"
	"os"
	"os/exec"
	"path/filepath"
	"testing"
)

// CLIResult - captures command execution. Clean. Efficient.
type CLIResult struct {
	ExitCode int
	Stdout   string
	Stderr   string
}

func runCLI(args ...string) CLIResult {
	cmd := exec.Command("./config-cli", args...)
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	exitCode := 0
	if err := cmd.Run(); err != nil {
		if exitErr, ok := err.(*exec.ExitError); ok {
			exitCode = exitErr.ExitCode()
		}
	}

	return CLIResult{
		ExitCode: exitCode,
		Stdout:   stdout.String(),
		Stderr:   stderr.String(),
	}
}

// Argument parsing tests. Table-driven. Methodical.
func TestArgumentParsing(t *testing.T) {
	tests := []struct {
		name         string
		args         []string
		wantExitCode int
		wantInStderr string
	}{
		{"valid get command", []string{"get", "database.host"}, 0, ""},
		{"valid set command", []string{"set", "port", "8080"}, 0, ""},
		{"missing key for get", []string{"get"}, 2, "requires key argument"},
		{"missing value for set", []string{"set", "key"}, 2, "requires value argument"},
		{"unknown command", []string{"unknown"}, 2, "unknown command"},
		{"invalid flag", []string{"--invalid"}, 2, "unknown flag"},
		{"valid format flag", []string{"list", "--format", "json"}, 0, ""},
		{"invalid format value", []string{"list", "--format", "xml"}, 2, "invalid format"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			result := runCLI(tt.args...)
			if result.ExitCode != tt.wantExitCode {
				t.Errorf("exit code = %d, want %d", result.ExitCode, tt.wantExitCode)
			}
			if tt.wantInStderr != "" && !bytes.Contains([]byte(result.Stderr), []byte(tt.wantInStderr)) {
				t.Errorf("stderr missing %q", tt.wantInStderr)
			}
		})
	}
}

// Exit codes. Critical for scripting. Must be precise.
func TestExitCodes(t *testing.T) {
	tests := []struct {
		name     string
		args     []string
		wantCode int
	}{
		{"success returns 0", []string{"list"}, 0},
		{"runtime error returns 1", []string{"get", "nonexistent", "--config", "/nonexistent/path"}, 1},
		{"usage error returns 2", []string{"set"}, 2},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			result := runCLI(tt.args...)
			if result.ExitCode != tt.wantCode {
				t.Errorf("exit code = %d, want %d", result.ExitCode, tt.wantCode)
			}
		})
	}
}

// Output streams. Data to stdout. Errors to stderr. Discipline required.
func TestOutputStreams(t *testing.T) {
	tmpDir := t.TempDir()
	configPath := filepath.Join(tmpDir, "config.yaml")
	os.WriteFile(configPath, []byte("key: value\n"), 0644)

	t.Run("data goes to stdout", func(t *testing.T) {
		result := runCLI("get", "key", "--config", configPath)
		if result.Stdout == "" {
			t.Error("expected data on stdout")
		}
	})

	t.Run("errors go to stderr", func(t *testing.T) {
		result := runCLI("get", "key", "--config", "/nonexistent")
		if result.Stderr == "" {
			t.Error("expected error on stderr")
		}
		if result.Stdout != "" {
			t.Error("error data should not appear on stdout")
		}
	})

	t.Run("quiet suppresses non-essential output", func(t *testing.T) {
		result := runCLI("set", "newkey", "newval", "--config", configPath, "--quiet")
		if result.Stdout != "" {
			t.Error("quiet mode should suppress stdout")
		}
	})
}

// File system operations. Permissions. Creation. Many failure modes.
func TestFileSystemOperations(t *testing.T) {
	t.Run("init creates config file", func(t *testing.T) {
		tmpDir := t.TempDir()
		configPath := filepath.Join(tmpDir, "newconfig.yaml")

		result := runCLI("init", "--config", configPath)
		if result.ExitCode != 0 {
			t.Fatalf("init failed: %s", result.Stderr)
		}
		if _, err := os.Stat(configPath); os.IsNotExist(err) {
			t.Error("config file not created")
		}
	})

	t.Run("permission denied handled gracefully", func(t *testing.T) {
		tmpDir := t.TempDir()
		os.Chmod(tmpDir, 0444)
		defer os.Chmod(tmpDir, 0755)

		configPath := filepath.Join(tmpDir, "config.yaml")
		result := runCLI("init", "--config", configPath)

		if result.ExitCode != 1 {
			t.Errorf("expected exit code 1, got %d", result.ExitCode)
		}
		if !bytes.Contains([]byte(result.Stderr), []byte("permission")) {
			t.Error("error should mention permission issue")
		}
	})
}

// Edge cases. Invalid YAML. Missing files. Ran simulations. Results conclusive.
func TestEdgeCases(t *testing.T) {
	t.Run("invalid YAML syntax", func(t *testing.T) {
		tmpDir := t.TempDir()
		configPath := filepath.Join(tmpDir, "bad.yaml")
		os.WriteFile(configPath, []byte("invalid: yaml: content: ["), 0644)

		result := runCLI("validate", "--config", configPath)
		if result.ExitCode != 1 {
			t.Error("should fail on invalid YAML")
		}
	})

	t.Run("empty config file", func(t *testing.T) {
		tmpDir := t.TempDir()
		configPath := filepath.Join(tmpDir, "empty.yaml")
		os.WriteFile(configPath, []byte(""), 0644)

		result := runCLI("list", "--config", configPath)
		if result.ExitCode != 0 {
			t.Error("empty config should be valid")
		}
	})

	t.Run("nested key access", func(t *testing.T) {
		tmpDir := t.TempDir()
		configPath := filepath.Join(tmpDir, "nested.yaml")
		os.WriteFile(configPath, []byte("database:\n  host: localhost\n"), 0644)

		result := runCLI("get", "database.host", "--config", configPath)
		if !bytes.Contains([]byte(result.Stdout), []byte("localhost")) {
			t.Error("should retrieve nested value")
		}
	})
}
